\label{Zacken}
    We denote by $\mathcal C$ and $\mathcal S$ the 1-periodic extensions to $\mathbb{R}$ of
    $$\mathcal C, \mathcal S: [0,1) \to \mathbb{R}, \quad \mathcal C(x):=4\left|x-\frac 1 2\right|-1, \quad \mathcal S(x):= \left|2-4\left|x-\frac 1 4\right|\right|-1.$$

\label{InvTtau}
    Let $q \in (1,\infty), d \in \mathbb{N}$ and $\tau \in \ell_1.$
    \begin{enumerate}[label=(\roman*)]
        \item The operator $T_\tau: L_q([0,1]^d) \to L_q([0,1]^d)$ is injective if, and only if, $\tau_0 \neq 0$.
        \item Let $\tau_1 \neq 0$ and $\tau^{-1}$ be its Dirichlet inverse. Assume $\tau^{-1} \in \ell_1,$ then $T_\tau$ is bijective and $T_\tau^{-1}=T_{\tau^{-1}}.$
    \end{enumerate}

\label{Mainbases}
    Let $q \in (1,\infty), d \in \mathbb{N}$ and $T \in \mathcal L(L_q([0,1]^d))$ be bijective, then $$\{T(1)\} \cup \{T(\sqrt 2 c_J), T(\sqrt 2 s_J): J \in  \mathbb{Z} ^d_{+\!\!>0}\} \subset L_q([0,1]^d)$$ is a Schauder basis and           
    in case $q=2$ a Riesz basis with optimal Riesz constants $A=\|T^{-1}\|^{-2}$ and $B=\|T\|^2$.

\begin{enumerate}[label=(\roman*)]
    \item For all $k \in \mathbb{N}$ the maps $\cos(2 \pi k \cdot), \sin(2 \pi k \cdot)$ are continuous and bounded by 1. Thus, for all $x \in [0,1]$ $$|C^\tau(x)|,|S^\tau(x)| \leq \sqrt 2 \sum \limits_{k=1}^\infty |\tau_k| = \sqrt 2 \|\tau\|_{\ell_1} < \infty$$ holds and the M-test of Weierstraß ensures uniform convergence and continuity of $C^\tau, S^\tau$. In particular, this implies Lebesgue measurability and $C^\tau, S^\tau \in L_q([0,1])$ as both functions are bounded (by $\sqrt 2 \|\tau\|_{\ell_1}).$
    \item This follows directly from combining Theorem \ref{Ttau}(i) and (iv) with Lemma \ref{Mainbases} and the calculation \begin{equation}
        T_\tau(1)=\sum \limits_{k=1}^\infty \tau_k=\tau_0, \quad T_\tau(\sqrt 2 c)=\sqrt 2 \sum \limits_{k=1}^\infty \tau _k c_k=C^\tau, \quad T_\tau(\sqrt 2 s)=\sqrt 2 \sum \limits_{k=1}^\infty \tau _k s_k=S^\tau.
    \end{equation} 
\end{enumerate}

\label{Coeff}
    Let $q \in (1,\infty), d \in \mathbb{N}, \tau \in \ell_1$ and $a,b: \mathbb{Z} ^d_{+\!\!>0} \to \mathbb{R}.$
    \begin{enumerate}[label=(\roman*)]
        \item If $\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J \sqrt 2 c_J + b_J \sqrt 2 s_J$ converges in $L_q([0,1]^d),$ it holds \begin{equation}
            T_\tau \Bigg(\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J \sqrt 2 c_J + b_J \sqrt 2 s_J \Bigg) = \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} (\tau *_da)_J \sqrt 2 c_J + (\tau*_db)_J \sqrt 2 s_J.
        \end{equation}
        \item Let $\tau_1 \neq 0.$ If $f=\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C^\tau_J + b_J S^\tau_J$ converges in $L_q([0,1]^d),$ it holds $a=\tau^{-1} *_d \hat a$ and $b=\tau^{-1}*_d \hat b$ where $\hat a_J:=\int_{[0,1]^d} f(x) \sqrt 2 c_J(x) \mathrm d x$ and $\hat b_J:=\int_{[0,1]^d} f(x) \sqrt 2 s_J(x) \mathrm d x$ for all $J \in  \mathbb{Z} ^d_{+\!\!>0}.$
    \end{enumerate}

\begin{enumerate}[label=(\roman*)]
        \item Because $T_\tau$ is linear and bounded, by Theorem \ref{Ttau}(i) we get \begin{align*} T_\tau\Bigg(\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J \sqrt 2 c_J + b_J \sqrt 2 s_J\Bigg) &= \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J \sqrt 2 T_\tau(c_J) + b_J \sqrt 2 T_\tau(s_J) \\ &= \sum \limits_{k=1}^\infty \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} \tau_k a_J \sqrt 2 c_{kJ} + \tau_k b_J \sqrt 2 s_{kJ}\\&=\sum \limits_{N \in  \mathbb{Z} ^d_{+\!\!>0}} \left(\sum \limits_{\substack{(k,J) \in \mathbb{N} \times  \mathbb{Z} ^d_{+\!\!>0} \\ kJ=N}} \tau_k a_J \right) \sqrt 2 c_N + \left(\sum \limits_{\substack{(k,J) \in \mathbb{N} \times  \mathbb{Z} ^d_{+\!\!>0} \\ kJ=N}} \tau_k b_J \right) \sqrt 2 s_N \\ &= \sum \limits_{N \in  \mathbb{Z} ^d_{+\!\!>0}} (\tau*_da)_N \sqrt 2 c_N + (\tau*_db)_J \sqrt 2 s_N. \end{align*}
        \item The sequences $\hat a, \hat b: \mathbb{Z} ^d_{+\!\!>0}\rightarrow \mathbb{R}$ are well-defined because every integral converges by Hölder's inequality and Lemma \ref{ZystemSRBasis}(i) applied to the conjugate exponent $q'.$ The Dirichlet inverse of $\tau$ exists because $\tau_1 \neq 0$ is assumed. We calculate \begin{align*} \hat a_J=\int_{[0,1]^d} f(x) \sqrt 2 c_J(x) \mathrm d x &= \sum \limits_{N \in  \mathbb{Z} ^d_{+\!\!>0}} a_N \int_{[0,1]^d} C^\tau_N(x) \sqrt 2c_J(x) \mathrm d x \\ &= \sum \limits_{N \in  \mathbb{Z} ^d_{+\!\!>0}} \sum \limits_{k=1}^\infty a_N \tau_k \int_{[0,1]^d} \sqrt 2 c_{kN}(x) \sqrt 2 c_J(x) \mathrm d x = \sum \limits_{\substack{(k,N) \in \mathbb{N} \times  \mathbb{Z} ^d_{+\!\!>0} \\ kN=J}} \tau_k a_N = (\tau *_da)_J. \end{align*} Using Lemma \ref{dDirichlet}(ii),(iii) we deduce $$a=e*_da=(\tau^{-1}*\tau)*_da=\tau^{-1}*_d(\tau*_da)=\tau^{-1}*_d\hat a.$$ Switching $a$ with $b, c$ with $s$ as well as $C^\tau$ with $S^\tau$ shows $\hat b_J=(\tau *_d b)_J$ in the same way.
    \end{enumerate}

\label{MixedZystems}
    Let $q\in(1,\infty), d \in \mathbb{N}, k_0 \neq 0$ and $\tau, \lambda \in \ell_1$ such that $\mathcal Z^\tau, \ \mathcal Z^\lambda$ are Schauder bases of $L_q([0,1]^d).$ Then, the system $$\{k_0\}\cup \{C_J^\tau, S_J^\lambda: J \in  \mathbb{Z} ^d_{+\!\!>0}\}$$ is a Schauder basis of $L_q([0,1]^d)$ as well.  

    If $q=2,$ it is a Riesz basis, if $\mathcal Z^\tau$ and $\mathcal Z^\lambda$ are Riesz bases with constants $A_\tau \leq B_\tau$ and $A_\lambda \leq B_\lambda,$ where $$A=\min\{k_0^2,A_\tau, A_\lambda\}, \quad B=\max\{k_0^2,B_\tau, B_\lambda\}.$$

We will prove this theorem in four steps: First we will show that any $g \in L_q([0,1]^d)$ can uniquely be represented as $g=g_0+g_++g_-,$ where $g_0$ is a constant, $g_+$ is even with vanishing mean and $g_-$ is odd (with vanishing mean). Then, we will use this to find representations with respect to the given system and afterwards show uniqueness. Lastly, we will estimate the Riesz constants. Let $g \in L_q([0,1]^d).$

\textbf{Step 1:} We set $g_0:=\int_{[0,1]^d} g(x) \ \mathrm d x.$ Then, $g= g_0 + g_+ + g_-,$ where $$g_+(x):=\frac{g(x)+g(-x)}2-g_0, \quad g_-(x) := \frac{g(x)-g(-x)}2,$$ is a suitable representation. We will prove that it is the only one.

Assume there would be another representation $g=g_0'+g_+'+g_-'.$ Integrating $g$ over $[0,1]^d$ shows $g_0'=g_0.$ Now from $g_0+g_++g_-=g=g_0'+g_+'+g_-'$ we get $g_+-g_+'=g_-'-g_-.$ The left hand side is an even function, while the right hand side is an odd function. The only such function is the zero function, since any odd and even function $h$ satisfies $-h(x)=h(-x)=h(x)$ and consequently $h(x)=0$ for almost every $x \in [0,1]^d.$ Whence, $g_+-g_+'=0=g_-'-g_-$ and $g_+=g_+', g_-=g_-'$ follow.

\textbf{Step 2:}
Since $\mathcal Z^\tau$ is a Schauder basis of $L_q([0,1]^d)$, we can find a representation of $g_+$ with respect to {$\mathcal Z^\tau,$} that is, $a_J, b_J, \gamma_0 \in \mathbb{R}$ such that $$g_+=\gamma_0+\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C_J^\tau + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} b_J S_J^\tau.$$ Integrating over $[0,1]^d$ shows $\gamma_0=0.$ Furthermore, since $g_+$ is an even function, $$g_+(x)=\frac{g_+(x)+g_+(-x)}{2}=\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J \frac{C_J^\tau(x)+C_J^\tau(-x)}2 + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} b_J \frac{S_J^\tau(x)+S_J^\tau(-x)}2 = \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C_J^\tau$$ follows. Similarly, $g_-$ can be expressed with respect to $\mathcal Z^\lambda$ as $g_-(x)=\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a'_J S_J^\lambda$ giving $$g=g_0+g_++g_-=\frac{\int_{[0,1]^d} g(x) \ \mathrm d x} {k_0} \cdot k_0 + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C_J^\tau + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a'_J S_J^\lambda.$$ 

\textbf{Step 3:}
Let $$g=b_0 \cdot k_0+ \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} b_J C_J^\tau + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} b'_J S_J^\lambda$$ be any representation of $g$ with respect to the system. The coefficients $b_J, b_J'$ are uniquely determined by $g$ because of Proposition \ref{Coeff}(ii). Similarly $b_0$ is uniquely determined by $b_0 \cdot k_0 = \int_{[0,1]^d} g(x) \mathrm d x,$ since $k_0\neq 0.$


\textbf{Step 4:} Due to orthogonality we can estimate \begin{align*}
    \left\|a_0 \cdot k_0 + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C_J^\tau + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a'_J S_J^\lambda\right\|^2 &= a_0^2k_0^2 + \left\|\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C_J^\tau\right\|^2 + \left\| \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a'_J S_J^\lambda\right\|^2 \\ &\leq k_0^2 \cdot a_0^2 + B_\tau \cdot \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}}a_J^2 + B_\lambda \cdot \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}}(a_J')^2 \\ &\leq \max\{k_0^2,B_\tau, B_\lambda\} \left(a_0^2+\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}}(a_J^2+(a_J')^2)\right) \end{align*} and similarly $$\left\|a_0 \cdot k_0 + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a_J C_J^\tau + \sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}} a'_J S_J^\lambda\right\|^2 \geq \\ \min\{k_0^2,A_\tau, A_\lambda\} \left(a_0^2+\sum \limits_{J \in  \mathbb{Z} ^d_{+\!\!>0}}(a_J^2+(a_J')^2)\right).$$

Because $\ell_1$ is a vector space it holds $\frac{\tau \pm \lambda}{2} \in \ell_1.$ By Theorem \ref{Ttau}(i), $T$ is linear and bounded. It holds \begin{align*}
    T(1) &= \sum \limits_{k=1}^\infty \frac{\tau_k + \lambda_k}2 + \sum \limits_{k=1}^\infty \frac{\tau_k-\lambda_k}{2} = \sum \limits_{k=1}^\infty \tau_k = \tau_0, \\ T(\sqrt 2 c_J) &= \sqrt 2 \sum \limits_{k=1}^\infty \frac{\tau_k + \lambda_k}2c_{kJ} + \sqrt 2 \sum \limits_{k=1}^\infty \frac{\tau_k - \lambda_k}2c_{kJ}=\sqrt 2 \sum \limits_{k=1}^\infty \tau_kc_{kJ}=         
    C^\tau_J, \\
    T(\sqrt 2 s_J) &= \sqrt 2\sum \limits_{k=1}^\infty \frac{\tau_k + \lambda_k}2s_{kJ} - \sqrt 2\sum \limits_{k=1}^\infty \frac{\tau_k - \lambda_k}2s_{kJ} = \sqrt 2 \sum \limits_{k=1}^\infty \lambda_k s_{kJ}=S^\lambda_J.
\end{align*}

Using Theorem \ref{AlgTtau} parts (i) and (ii) are easily seen, we only prove (iii).

    The sequence $\tau^{*2}-\lambda^{*2}$ admits a Dirichlet inverse, since $(\tau^{*2}-\lambda^{*2})_1=(\tau*\tau)_1-(\lambda*\lambda)_1=         
    \tau^2_1-\lambda^2_1 \neq 0$ holds because of the assumption $|\tau_1| \neq |\lambda_1|$. Because the inverse was further assumed to be summable, the operator $T_{(\tau^{*2}-\lambda^{*2})^{-1}*\tau}+T_{-(\tau^{*2}-\lambda^{*2})^{-1}*\lambda}^R$ is well-defined. Lastly, using (ii) we check \begin{align*}
        (T_\tau+T_\lambda^R)(T_{(\tau^{*2}-\lambda^{*2})^{-1}*\tau}+T_{-(\tau^{*2}-\lambda^{*2})^{-1}*\lambda}^R)=T_{(\tau^{*2}-\lambda^{*2})*(\tau^{*2}-\lambda^{*2})^{-1}}+T^R_{(\lambda*\tau-\tau*\lambda)*(\tau^{*2}-\lambda^{*2})^{-1}}=T_e+T_0^R=\text{Id}.
    \end{align*}

\label{Example}
\begin{enumerate}[label=(\roman*)]
    \item \emph{The geometric sequence.} Let $r\in(-1,1)$ and $\tau_k:=r^k.$ Then $\sum_{n=1}^\infty |r|^n=\frac{|r|}{1-|r|}$ converges, whence $\tau\in\ell_1$. We check whether $2|\tau_1|>\|\tau\|_{\ell_1}$ holds. For $r=0$ this is not the case, so let $r\neq0.$ Then $$2|r|>\frac{|r|}{1-|r|}\ \text{ is equivalent to }\ 1-|r|>\frac12, \ \text{ that is, to }\ |r|<\frac12.$$ Whence Theorem~\ref{Basiscrit}(i) applies for every $r\in(-\frac12,\frac12)\setminus\{0\}$, and for $q=2$ it yields the Riesz constants $B=\big(\frac{|r|}{1-|r|}\big)^2$ and $A\geq\big(|r|\frac{1-2|r|}{1-|r|}\big)^2.$

    The functions $C^\tau, S^\tau$ can be written in closed form. For every $r\in(-1,1)$ and $x\in\mathbb{R}$ we have $|re^{2\pi ix}|=|r|<1$, and therefore
    \begin{align*}
        &\sum_{k=1}^\infty r^k\cos(2\pi kx)+i\sum_{k=1}^\infty r^k\sin(2\pi kx)
        =\sum_{k=1}^\infty \big(re^{2\pi ix}\big)^k=\frac{re^{2\pi ix}}{1-re^{2\pi ix}}
        =\frac{re^{2\pi ix}\big(1-re^{-2\pi ix}\big)}{\big(1-re^{2\pi ix}\big)\big(1-re^{-2\pi ix}\big)}\\
        &\qquad=\frac{re^{2\pi ix}-r^2}{1+r^2-2r\cos(2\pi x)}
        =\frac{\big(r\cos(2\pi x)-r^2\big)+ir\sin(2\pi x)}{1+r^2-2r\cos(2\pi x)}.
    \end{align*}
    Taking real and imaginary parts, we obtain $$C^\tau(x)=\sqrt2\,\frac{r\cos(2\pi x)-r^2}{1+r^2-2r\cos(2\pi x)}\quad\text{and}\quad S^\tau(x)=\sqrt2\,\frac{r\sin(2\pi x)}{1+r^2-2r\cos(2\pi x)}.$$
