    \item \emph{The exponential series.} Let $\tau_k:=\frac1{k!}.$ Then $\tau\in\ell_1$ and $\|\tau\|_{\ell_1}=e-1<2=2|\tau_1|$, so Theorem~\ref{Basiscrit}(i) applies, and for $q=2$ the Riesz constants are $B=(e-1)^2$ and $A\geq(3-e)^2.$ In $\mathbb C$ we compute
    \begin{align*}
        &\sum_{k=1}^\infty\frac{\cos(2\pi kx)}{k!}+i\sum_{k=1}^\infty\frac{\sin(2\pi kx)}{k!}
        =\sum_{k=1}^\infty\frac{\big(e^{2\pi ix}\big)^k}{k!}=\exp\big(\cos(2\pi x)+i\sin(2\pi x)\big)-1\\
        &\qquad=e^{\cos(2\pi x)}\big(\cos(\sin(2\pi x))+i\sin(\sin(2\pi x))\big)-1,
    \end{align*}
    which shows $$C^\tau(x)=\sqrt2\,e^{\cos(2\pi x)}\cos(\sin(2\pi x))-\sqrt2\quad\text{and}\quad S^\tau(x)=\sqrt2\,e^{\cos(2\pi x)}\sin(\sin(2\pi x)).$$
