\end{enumerate}

\label{SKP2}
    Let $d \in \mathbb{N}, \alpha,\beta \in  \mathbb{Z} ^d_{+\!\!>0}.$
    \begin{enumerate}[label=(\roman*)]
        \item If $\alpha,\beta$ are oddly co-linear, that is, if there are $p,q \in \mathbb{N}_0$ such that $\alpha = \frac {2p+1} {2q+1} \beta,$ and $\gcd(2p+1,2q+1)=1,$ then \begin{align*}
        3 \langle \mathcal C_\alpha, \mathcal C_\beta \rangle = \frac 1 {(2p+1)^2(2q+1)^2} \quad \text{ and } \quad
        3 \langle \mathcal S_\alpha, \mathcal S_\beta \rangle = \frac {(-1)^{p+q}} {(2p+1)^2(2q+1)^2}.  
        \end{align*}
        \item If $\alpha, \beta$ are not oddly co-linear, then \[\langle \mathcal C_\alpha, \mathcal C_\beta \rangle = 0 = \langle \mathcal S_\alpha, \mathcal S_\beta \rangle.\]
        \item Further, \[\langle \mathcal C_\alpha, \mathcal S_\beta \rangle = 0.\]
    \end{enumerate}

Note that $$B_{ij}=(DAD)_{ij}=\sum \limits_{k=1}^n (DA)_{ik} D_{kj} = (DA)_{ij} D_{jj} = \sum \limits_{k=1}^n D_{ik} A_{kj} D_{jj} = D_{ii}D_{jj}A_{ij}$$ holds true for all $1 \leq i,j \leq n.$ Similarly, $D^{\dagger k}$ is also diagonal, such that for all $1 \leq i,j \leq n-1$ it holds \begin{align*} (D^{\dagger k} A^{\dagger k} D^{\dagger k})_{ij}=D^{\dagger k}_{ii} D^{\dagger k}_{jj} A^{\dagger k}_{ij} = \begin{cases}
    D_{ii}D_{jj}A_{ij} &\text{ if } 1 \leq i,j < k,\\
    D_{ii}D_{(j+1)(j+1)}A_{i(j+1)} &\text{ if } 1 \leq i < k \leq j,\\
    D_{(i+1)(i+1)}D_{jj}A_{(i+1)j} &\text{ if } 1 \leq j < k \leq i,\\
    D_{(i+1)(i+1)}D_{(j+1)(j+1)}A_{(i+1)(j+1)} &\text{ if } k \leq i,j, \\
\end{cases} = (DAD)^{\dagger k}_{ij} = B^{\dagger k}_{ij}. \end{align*}
